/** Tüm ikonları sayfada tek seferde 'sprite' olarak basar (wp_body_open). */
function fj_icon_sprite() {
	echo '<svg xmlns="http://www.w3.org/2000/svg" width="0" height="0" style="position:absolute" aria-hidden="true" focusable="false">';
	foreach ( fj_icon_paths() as $name => $d ) {
		echo '<symbol id="i-' . esc_attr( $name ) . '" viewBox="0 0 20 20"><path d="' . esc_attr( $d ) . '"/></symbol>';
	}
	echo '</svg>';
}
add_action( 'wp_body_open', 'fj_icon_sprite', 1 );

/** Bir ikon yazdırır / döndürür. */
function fj_icon( $name, $class = '', $echo = true ) {
	$html = '<svg class="icon ' . esc_attr( $class ) . '" width="20" height="20" fill="currentColor" aria-hidden="true" focusable="false"><use href="#i-' . esc_attr( $name ) . '"/></svg>';
	if ( $echo ) { echo $html; return ''; } // phpcs:ignore WordPress.Security.EscapeOutput
	return $html;
}
